describe("planReminderSend", () => {
  it("programme le rappel 24 h avant la réservation par défaut", () => {
    const reservation = makeReservation({
      scheduledAt: new Date("2026-06-13T19:00:00-04:00"),
    });

    const sendAt = planReminderSend(reservation);

    expect(sendAt.toISOString()).toBe(new Date("2026-06-12T19:00:00-04:00").toISOString());
  });

  it("respecte un délai configurable en heures", () => {
    const reservation = makeReservation({
      scheduledAt: new Date("2026-06-13T19:00:00-04:00"),
    });

    const sendAt = planReminderSend(reservation, { hoursBefore: 3 });

    expect(sendAt.toISOString()).toBe(new Date("2026-06-13T16:00:00-04:00").toISOString());
  });

  it("ne programme jamais d'envoi après 21 h", () => {
    // Réservation à 22 h → 24 h avant = 22 h la veille → replié à 21 h
    const reservation = makeReservation({
      scheduledAt: new Date("2026-06-13T22:00:00-04:00"),
    });

    const sendAt = planReminderSend(reservation);

    expect(sendAt.getHours()).toBeLessThanOrEqual(21);
  });

  it("ne programme jamais d'envoi avant 8 h", () => {
    // Réservation déjeuner à 8 h → 24 h avant = 8 h la veille, trop tôt → replié à 8 h
    const reservation = makeReservation({
      scheduledAt: new Date("2026-06-13T08:00:00-04:00"),
    });

    const sendAt = planReminderSend(reservation);

    expect(sendAt.getHours()).toBeGreaterThanOrEqual(8);
  });
});

